// Bundles prompts/*.md and prompts/*.schema.json into packages/core/src/prompts.generated.ts so both
// executors (Node and Workers, which has no filesystem) use byte-identical templates.
// Usage: node scripts/embed-prompts.mjs [--check]   (--check exits 1 if the generated file is stale)
import { readFileSync, readdirSync, writeFileSync } from "node:fs";

const promptsDir = new URL("../prompts/", import.meta.url);
const outFile = new URL("../packages/core/src/prompts.generated.ts", import.meta.url);

const names = readdirSync(promptsDir)
  .filter((f) => f.endsWith(".md"))
  .map((f) => f.slice(0, -3))
  .sort();

const templates = {};
const schemas = {};
for (const name of names) {
  // Normalise line endings and drop the trailing newline so renders are identical on every OS.
  templates[name] = readFileSync(new URL(`${name}.md`, promptsDir), "utf8")
    .replace(/\r\n/g, "\n")
    .replace(/\n$/, "");
  schemas[name] = JSON.parse(readFileSync(new URL(`${name}.schema.json`, promptsDir), "utf8"));
}

const source = `// GENERATED by scripts/embed-prompts.mjs from prompts/*.md and prompts/*.schema.json — do not edit.
export const PROMPT_TEMPLATES = ${JSON.stringify(templates, null, 2)} as const;

export const PROMPT_SCHEMAS = ${JSON.stringify(schemas, null, 2)} as const;
`;

if (process.argv.includes("--check")) {
  const current = readFileSync(outFile, "utf8").replace(/\r\n/g, "\n");
  if (current !== source) {
    console.error("prompts.generated.ts is stale — run: node scripts/embed-prompts.mjs");
    process.exit(1);
  }
  console.log("prompts.generated.ts is up to date");
} else {
  writeFileSync(outFile, source);
  console.log(`wrote ${names.length} prompts to packages/core/src/prompts.generated.ts`);
}
